@Override
    public void copyFrom(ComponentContainer other) {
        for (ComponentKey<?> key : this.keys()) {
            Component theirs = key.getInternal(other);
            Component ours = key.getInternal(this);
            assert ours != null;

            if (theirs != null && !ours.equals(theirs)) {
                if (ours instanceof CopyableComponent) {
                    @SuppressWarnings("unchecked") CopyableComponent<Component> copyable = (CopyableComponent<Component>) ours;
                    copyable.copyFrom(theirs);
                } else {
                    NbtCompound tag = new NbtCompound();
                    theirs.writeToNbt(tag);
                    ours.readFromNbt(tag);
                }
            }
        }
    }

@Override
    public void fromTag(NbtCompound tag) {
        if(tag.contains(NBT_KEY, NbtType.LIST)) {
            NbtList componentList = tag.getList(NBT_KEY, NbtType.COMPOUND);
            for (int i = 0; i < componentList.size(); i++) {
                NbtCompound nbt = componentList.getCompound(i);
                ComponentKey<?> type = ComponentRegistry.get(new Identifier(nbt.getString("componentId")));
                if (type != null) {
                    Component component = type.getInternal(this);
                    if (component != null) {
                        component.readFromNbt(nbt);
                    }
                }
            }
        } else if (tag.contains("cardinal_components", NbtType.COMPOUND)) {
            NbtCompound componentMap = tag.getCompound(NBT_KEY);

            for (ComponentKey<?> key : this.keys()) {
                String keyId = key.getId().toString();

                if (componentMap.contains(keyId, NbtType.COMPOUND)) {
                    Component component = key.getInternal(this);
                    assert component != null;
                    component.readFromNbt(componentMap.getCompound(keyId));
                    componentMap.remove(keyId);
                }
            }

            ComponentsInternals.logDeserializationWarnings(componentMap.getKeys());
        }
    }

@Override
    public NbtCompound toTag(NbtCompound tag) {
        if(this.hasComponents()) {
            NbtCompound componentMap = null;
            NbtCompound componentTag = new NbtCompound();

            for (ComponentKey<?> type : this.keys()) {
                Component component = type.getFromContainer(this);
                component.writeToNbt(componentTag);

                if (!componentTag.isEmpty()) {
                    if (componentMap == null) {
                        componentMap = new NbtCompound();
                        tag.put(NBT_KEY, componentMap);
                    }

                    componentMap.put(type.getId().toString(), componentTag);
                    componentTag = new NbtCompound();   // recycle tag objects if possible
                }
            }
        }
        return tag;
    }

@Override
    public String toString() {
        Iterator<ComponentKey<?>> i = this.keys().iterator();

        if (! i.hasNext()) {
            return "{}";
        }

        StringBuilder sb = new StringBuilder();
        sb.append('{');
        for (;;) {
            ComponentKey<?> key = i.next();
            Component value = key.getInternal(this);
            sb.append(key);
            sb.append('=');
            sb.append(value);

            if (! i.hasNext()) {
                return sb.append('}').toString();
            }

            sb.append(',').append(' ');
        }
    }

@Override
    public synchronized <T extends Component> ComponentKey<T> getOrCreate(Identifier componentId, Class<T> componentClass) {
        Preconditions.checkArgument(Component.class.isAssignableFrom(componentClass), "Component interface must extend " + Component.class.getCanonicalName());
        // make sure 2+ components cannot get registered at the same time
        @SuppressWarnings("unchecked")
        ComponentKey<T> existing = (ComponentKey<T>) this.get(componentId);

        if (existing != null) {
            if (existing.getComponentClass() != componentClass) {
                throw new IllegalStateException("Registered component " + componentId + " twice with 2 different classes: " + existing.getComponentClass() + ", " + componentClass);
            }
            return existing;
        } else {
            Class<? extends ComponentKey<?>> generated = CcaBootstrap.INSTANCE.getGeneratedComponentTypeClass(componentId);

            if (generated == null) {
                throw new IllegalStateException(componentId + " was not registered through mod metadata or plugin");
            }

            ComponentKey<T> registered = this.instantiateStaticType(generated, componentId, componentClass);
            this.keys.put(componentId, registered);
            return registered;
        }
    }

private <T extends Component> ComponentKey<T> instantiateStaticType(Class<? extends ComponentKey<?>> generated, Identifier componentId, Class<T> componentClass) {
        try {
            @SuppressWarnings("unchecked") ComponentKey<T> ret = (ComponentKey<T>) generated.getConstructor(Identifier.class, Class.class).newInstance(componentId, componentClass);
            return ret;
        } catch (InstantiationException | IllegalAccessException | InvocationTargetException | NoSuchMethodException e) {
            throw new IllegalStateException("Failed to create statically declared component type", e);
        }
    }

