public static void init() {
        if (FabricLoader.getInstance().isModLoaded("fabric-networking-api-v1")) {
            BlockEntitySyncCallback.EVENT.register((player, tracked) -> {
                ComponentProvider provider = (ComponentProvider) tracked;

                for (ComponentKey<?> key : provider.getComponentContainer().keys()) {
                    key.syncWith(player, provider);
                }
            });
            BlockEntitySyncAroundCallback.EVENT.register(tracked -> {
                for (ComponentKey<?> key : ((ComponentProvider) tracked).getComponentContainer().keys()) {
                    tracked.syncComponent(key);
                }
            });
        }
        if (FabricLoader.getInstance().isModLoaded("fabric-lifecycle-events-v1")) {
            ServerBlockEntityEvents.BLOCK_ENTITY_LOAD.register((be, world) -> ((ComponentProvider) be).getComponentContainer().onServerLoad());
            ServerBlockEntityEvents.BLOCK_ENTITY_UNLOAD.register((be, world) -> ((ComponentProvider) be).getComponentContainer().onServerUnload());
        }
    }

public static void initClient() {
        if (FabricLoader.getInstance().isModLoaded("fabric-networking-api-v1")) {
            ClientPlayNetworking.registerGlobalReceiver(CardinalComponentsBlock.PACKET_ID, (client, handler, buffer, res) -> {
                try {
                    Identifier blockEntityTypeId = buffer.readIdentifier();
                    BlockPos position = buffer.readBlockPos();
                    Identifier componentTypeId = buffer.readIdentifier();
                    BlockEntityType<?> blockEntityType = Registries.BLOCK_ENTITY_TYPE.get(blockEntityTypeId);
                    ComponentKey<?> componentType = ComponentRegistry.get(componentTypeId);

                    if (componentType == null || blockEntityType == null) {
                        return;
                    }

                    buffer.retain();

                    client.execute(() -> {
                        try {
                            componentType.maybeGet(blockEntityType.get(client.world, position))
                                .filter(c -> c instanceof AutoSyncedComponent)
                                .ifPresent(c -> ((AutoSyncedComponent) c).applySyncPacket(buffer));
                        } finally {
                            buffer.release();
                        }
                    });
                } catch (Exception e) {
                    ComponentsInternals.LOGGER.error("Error while reading block entity components from network", e);
                    throw e;
                }
            });
        }
        if (FabricLoader.getInstance().isModLoaded("fabric-lifecycle-events-v1")) {
            ClientBlockEntityEvents.BLOCK_ENTITY_LOAD.register((be, world) -> ((ComponentProvider) be).getComponentContainer().onServerLoad());
            ClientBlockEntityEvents.BLOCK_ENTITY_UNLOAD.register((be, world) -> ((ComponentProvider) be).getComponentContainer().onServerUnload());
        }
    }

public static ComponentContainer createComponents(BlockEntity blockEntity) {
        Class<? extends BlockEntity> entityClass = blockEntity.getClass();
        ComponentContainer.Factory<BlockEntity> existing = entityContainerFactories.get(entityClass);

        return Objects.requireNonNullElseGet(
            existing,
            () -> getBeComponentFactory(entityClass)
        ).createContainer(blockEntity);
    }

private static synchronized ComponentContainer.Factory<BlockEntity> getBeComponentFactory(Class<? extends BlockEntity> entityClass) {
        // need to check again despite synchronization, because
        // 1- recursive calls
        // 2- the factory may have been generated while waiting from createComponents
        ComponentContainer.Factory<BlockEntity> existing = entityContainerFactories.get(entityClass);
        if (existing != null) return existing;

        ComponentContainer.Factory<BlockEntity> factory;
        if (StaticBlockComponentPlugin.INSTANCE.requiresStaticFactory(entityClass)) {
            factory = StaticBlockComponentPlugin.INSTANCE.buildDedicatedFactory(entityClass);
        } else {
            @SuppressWarnings("unchecked") var superclass = (Class<? extends BlockEntity>) entityClass.getSuperclass();
            assert BlockEntity.class.isAssignableFrom(superclass) : "requiresStaticFactory returned false on BlockEntity?";
            factory = /* recursive call */ getBeComponentFactory(superclass);
        }
        entityContainerFactories.put(entityClass, factory);
        return factory;
    }

private static String getSuffix(Class<? extends BlockEntity> key) {
        return "BlockEntityImpl_%s_%s".formatted(key.getSimpleName(), Integer.toHexString(key.getName().hashCode()));
    }

