    public void chunksSerialize(TestContext ctx) {
        ChunkPos pos = new ChunkPos(ctx.getAbsolutePos(new BlockPos(1, 0, 1)));
        Chunk c = new WorldChunk(ctx.getWorld(), pos);
        c.getComponent(Vita.KEY).setVitality(42);
